formula_sources.getBestiaryThreshold:
function getBestiaryThreshold(recLevel) {
                    recLevel = Math.max(1, parseInt(recLevel, 10) || 1);
                    const brackets = [
                        [10, 1000], [20, 1600], [30, 2400], [40, 3200], [50, 4000],
                        [60, 5000], [70, 6000], [80, 7000], [90, 8000], [100, 9200],
                        [110, 10400], [120, 12000]
                    ];
                    for (const [maxLevel, threshold] of brackets) {
                        if (recLevel <= maxLevel) return threshold;
                    }
                    return 14000; // nível 121-2000
                }

formula_sources.getBestiaryBonus:
function getBestiaryBonus(name) {
                    const notCompleted = { completed: false, dmgMult: 1.0, lootMult: 1.0 };
                    if (!name) return notCompleted;
                    const recLevel = getRecLevelForMonsterName(name);
                    if (recLevel === null) return notCompleted;
                    const kills = (playerState.bestiaryKills && playerState.bestiaryKills[name]) || 0;
                    const threshold = getBestiaryThreshold(recLevel);
                    const completed = kills >= threshold;
                    return {
                        completed,
                        dmgMult: completed ? 1.10 : 1.0,
                        lootMult: completed ? 1.05 : 1.0
                    };
                }

formula_sources.getBossiaryBonusForTier:
function getBossiaryBonusForTier(tier) {
                    const kills = getBossiaryKillsForTier(tier);
                    const complete = kills >= bossiaryThreshold;
                    const dmgPct = (complete ? 5 : 0) + (bossiaryCompletedCount * 0.25);
                    const bonusItemPct = (complete ? 5 : 0) + (bossiaryCompletedCount * 0.25);
                    return {
                        kills,
                        complete,
                        dmgMult: 1 + (dmgPct / 100),
                        dmgPct,
                        bonusItemPct
                    };
                }

formula_sources.getBossLootRows:
function getBossLootRows(bossKey) {
                    if (!bossDb || !bossDb[bossKey]) return [];
                    const boss = bossDb[bossKey];
                    const rowsById = {};

                    if (boss.special_loot && typeof boss.special_loot === 'object') {
                        Object.entries(boss.special_loot).forEach(([itemId, chance]) => {
                            const id = parseInt(itemId, 10) || 0;
                            if (id > 0) {
                                rowsById[id] = { id: id, chance: parseInt(chance, 10) || 0 };
                            }
                        });
                    }

                    if (Array.isArray(boss.loot_pool)) {
                        boss.loot_pool.forEach(entry => {
                            const id = parseInt(entry.id || 0, 10) || 0;
                            if (id > 0) {
                                if (!rowsById[id]) rowsById[id] = { id: id, chance: 0 };
                                rowsById[id].chance = Math.min(100000, rowsById[id].chance + (parseInt(entry.chance || 0, 10) || 0));
                            }
                        });
                    }

                    return Object.values(rowsById).sort((a, b) => b.chance - a.chance || a.id - b.id);
                }

formula_sources.preyBonusLabel:
function preyBonusLabel(bonus, short) {
                    if (bonus === 'defense') return short ? '-20% dano recebido' : '-20% de dano recebido';
                    if (bonus === 'loot') return short ? '+20% loot' : '+20% de loot';
                    if (bonus === 'bestiary') return short ? '2x bestiário' : '2x kills de bestiário';
                    return short ? '+20% dano' : '+20% de dano causado';
                }
